import type { Project } from './content-model';

/*
 * Placeholder device mockups (public/mockups, generated by
 * scripts/generate-mockups.py). They only show for projects that have no
 * images of their own; adding real images in admin replaces them.
 */
const VARIANTS = ['blue', 'orange', 'violet', 'green'] as const;

function variantFor(key: string) {
  let hash = 0;
  for (let i = 0; i < key.length; i += 1) hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
  return VARIANTS[hash % VARIANTS.length];
}

export function projectImageList(project: Pick<Project, 'previewImages' | 'blocks'>) {
  if (project.previewImages && project.previewImages.length > 0) return project.previewImages;
  return (project.blocks || []).filter((block) => block.type === 'image').map((block) => block.content);
}

/** Device mockups for hover previews and detail heroes. */
export function placeholderMockups(key: string) {
  const v = variantFor(key);
  return [`/mockups/laptop-${v}.svg`, `/mockups/phone-${v}-0.svg`, `/mockups/phone-${v}-1.svg`, `/mockups/phone-${v}-2.svg`];
}

/** A bare phone screen, for places that already draw their own phone frame. */
export function placeholderScreen(key: string) {
  return `/mockups/screen-${variantFor(key)}-0.svg`;
}

/** Screen artwork for the home reel's devices, varied by position so neighbours differ. */
export function reelPlaceholder(device: 'laptop' | 'phone', index: number) {
  const v = VARIANTS[index % VARIANTS.length];
  return device === 'laptop'
    ? `/mockups/laptop-screen-${v}.svg`
    : `/mockups/screen-${v}-${Math.floor(index / 2) % 3}.svg`;
}
